using W=McgsInternalBridge.NativeStrategyWorkingModelEditing;
namespace McgsInternalBridge {
 internal static partial class NativeReferencedPageEditing {
  internal sealed class ReferenceProgCompilerContract:IDisposable {
   internal const string ContractSha="be8c3dba3d581edf0cdc7357a9428f4d5f9e2ca6cc9152b846585d2918316913";
   sealed class Item {internal int Id,Row;internal string Name,Source;internal W.ProgSourceNormalization Normalization;}
   readonly Dictionary<string,object> action;readonly W.Api api;readonly W.TypedContract typed;readonly W.ArchiveWorkspace archive;readonly List<Item> items=new List<Item>();readonly Dictionary<int,W.OwnedStrategyGeneration> generators=new Dictionary<int,W.OwnedStrategyGeneration>();readonly Dictionary<string,object> generatedCaches=new Dictionary<string,object>();readonly List<object> generationEvidence=new List<object>();bool entered,disposed;
   static string Key(int id,int row){return id+":"+row;}
   static Dictionary<string,object> Marker(){return new Dictionary<string,object>{{"original_reference_rename_prog_compiler_result",true}};}
   static object Clone(object value){return new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue,RecursionLimit=256}.DeserializeObject(W.Json(value));}
   internal static ReferenceProgCompilerContract Prepare(Api references,Dictionary<string,object> action,Dictionary<string,object> before){object value;if(!Map(action["after"]).TryGetValue("reference_prog_compilation",out value))return null;return new ReferenceProgCompilerContract(references,action,before,Map(value));}
   ReferenceProgCompilerContract(Api references,Dictionary<string,object> request,Dictionary<string,object> before,Dictionary<string,object> specification){action=request;
    string file=Path.Combine(NativeUsableEditPermit.DirectoryRoot,"page-control-prep","reference-prog-compiler-prep","reference-prog-compiler-contract.json");NativeMemory.Require(NativeMemory.Hash(file)==ContractSha,"Explicit reference Prog compiler contract changed.");
    NativeMemory.Require(specification.Count==2&&Object.Equals(specification["allow_original_compile_and_fixed_point"],true)&&specification.ContainsKey("targets"),"Reference Prog compiler needs its exact permission and explicit targets.");
    api=new W.Api(references.Engine,references.Context,references.Shared.Project);typed=new W.TypedContract(api);archive=new W.ArchiveWorkspace(api);try{var blocks=api.Base.Blocks();var views=api.Views();var seen=new HashSet<string>();var expected=Map(Map(action["after"])["rename_state"]);string targetPath=Convert.ToString(Map(before["target"])["path"]);
     foreach(object value in(IEnumerable)specification["targets"]){var row=Map(value);foreach(string k in row.Keys)NativeMemory.Require(k=="block_id"||k=="block_name"||k=="native_row_index"||k=="source"||k=="source_utf16le_hex"||k=="source_utf16le_sha256"||k=="expected_source_after_original_generate","Unknown reference compiler target field.");var item=new Item{Id=Num(row["block_id"]),Name=Convert.ToString(row["block_name"]),Row=Num(row["native_row_index"]),Source=W.Body(row)};NativeMemory.Require(seen.Add(Key(item.Id,item.Row))&&blocks.ContainsKey(item.Id)&&!views.ContainsKey(item.Id),"Reference compiler target is duplicate/absent or still has an open working document.");NativeMemory.Require(NativeStrategyProfile.ReadName(api.Base.Read.Existing,blocks[item.Id])==item.Name,"Reference compiler actual consumer block name differs.");var rows=api.Rows(NativeMemory.Add(blocks[item.Id],-4));NativeMemory.Require(item.Row>=0&&item.Row<rows.Count&&api.Class(NativeMemory.Ptr(rows[item.Row],8)).Name=="CStgyFuncProg","Only a declared actual native Prog row may derive its compiler cache.");NativeMemory.Require(api.CString(NativeMemory.Add(NativeMemory.Ptr(rows[item.Row],8),0x20))!=item.Source,"Reference compiler target source is unchanged.");string sourcePath=references.Path(blocks[item.Id]);bool incoming=false;foreach(object edgeValue in(IEnumerable)Map(Map(before["context"])["graph"])["edges"]){var edge=Map(edgeValue);if(Under(Convert.ToString(edge["source"]),sourcePath)&&Under(Convert.ToString(edge["target"]),targetPath))incoming=true;}NativeMemory.Require(incoming,"Reference compiler target is not an actual incoming consumer of the renamed object.");item.Normalization=new W.ProgSourceNormalization(api,item.Source,row);NativeMemory.Require(item.Normalization.Normalized==item.Source,"Reference compiler postimage must already be in exact original source normal form.");var expectedBlock=Block(expected["strategy_blocks"],item.Id,item.Name);var expectedNode=Node(expectedBlock,item.Row);NativePageControlPreparation.Same(Marker(),Map(expectedNode["serialized_fields"])["byte_arrays@0xC"],"Expected reference consumer must explicitly mark only the declared Prog compiler member as derived.");Source(expectedNode,item.Source);items.Add(item);}
     NativeMemory.Require(items.Count>0,"Reference compiler target list is empty.");foreach(Item item in items)if(!generators.ContainsKey(item.Id)){var indexes=new List<int>();foreach(Item same in items)if(same.Id==item.Id)indexes.Add(same.Row);var generation=new W.OwnedStrategyGeneration(typed,action,-1,null,indexes);generation.RequireProductBlock(NativeMemory.Add(blocks[item.Id],-4));generators.Add(item.Id,generation);}
    }catch{Dispose();throw;}}
   static Dictionary<string,object> Block(object values,int id,string name){Dictionary<string,object> found=null;foreach(object value in(IEnumerable)values){var row=Map(value);if(Num(row["block_id"])==id){NativeMemory.Require(found==null&&Convert.ToString(row["block_name"])==name,"Reference compiler catalog target name/unique ID differs.");found=row;}}NativeMemory.Require(found!=null,"Reference compiler block is absent from complete expected/current consumer catalog.");return found;}
   static Dictionary<string,object> Node(Dictionary<string,object> block,int index){var rows=W.MList(block["persistent_rows"]);NativeMemory.Require(index>=0&&index<rows.Count&&Num(Map(rows[index])["native_row_index"])==index,"Reference compiler persistent row index differs.");var node=Map(Map(rows[index])["action"]);NativeMemory.Require(Convert.ToString(node["class_name"])=="CStgyFuncProg","Reference compiler target class differs.");return node;}
   static void Source(Dictionary<string,object> node,string source){var expected=new Dictionary<string,object>{{"text",source},{"utf16le_hex",W.H(W.RawText(source))}};NativePageControlPreparation.Same(expected,Map(node["serialized_fields"])["strings@0x20"],"Reference rename differs from the declared complete Prog body.");}
   internal void ValidateBefore(){NativeMemory.Require(!disposed&&!entered,"Reference compiler is disposed/already entered.");api.Current();var blocks=api.Base.Blocks();var views=api.Views();foreach(Item item in items){NativeMemory.Require(blocks.ContainsKey(item.Id)&&!views.ContainsKey(item.Id)&&NativeStrategyProfile.ReadName(api.Base.Read.Existing,blocks[item.Id])==item.Name,"Reference compiler consumer identity/model changed before mutation.");item.Normalization.ValidateBefore();}foreach(var item in generators)item.Value.ValidateProductBefore();}
   internal void ValidatePersistence(NativeUsableEditPermit.Plan plan){foreach(int id in generators.Keys)plan.RequireRelatedStrategyPersistence(action,id);}
   internal object Projection(object catalog,bool expected){var copy=Clone(catalog);foreach(Item item in items){var node=Node(Block(copy,item.Id,item.Name),item.Row);Source(node,item.Source);var fields=Map(node["serialized_fields"]);if(expected)NativePageControlPreparation.Same(Marker(),fields["byte_arrays@0xC"],"Expected derived cache permission changed.");else{var cache=Map(fields["byte_arrays@0xC"]);NativeMemory.Require(cache.ContainsKey("bytes")&&cache.ContainsKey("sha256")&&Object.Equals(cache["complete_payload_sha256"],true),"Actual Prog cache lacks its complete byte count/SHA projection.");object generated;if(generatedCaches.TryGetValue(Key(item.Id,item.Row),out generated))NativePageControlPreparation.Same(generated,cache,"Reference rename/compiler fixed-point cache differs from its exact recorded original result.");fields["byte_arrays@0xC"]=Marker();}}return copy;}
   internal void GenerateAfterBusinessValidation(NativeUsableEditPermit.Lease lease){NativeMemory.Require(!entered&&!disposed,"Reference compiler boundary cannot be replayed.");entered=true;foreach(var group in generators){lease.RequireApplying(action);lease.RequireRelatedStrategyPersistence(action,group.Key);NativeMemory.Require(!api.Views().ContainsKey(group.Key),"An opened working strategy would overwrite the canonical reference consumer.");IntPtr full=NativeMemory.Add(api.Base.Blocks()[group.Key],-4);foreach(Item item in items)if(item.Id==group.Key){var node=NativeMemory.Ptr(api.Rows(full)[item.Row],8);group.Value.RegisterProgSource(node,item.Source);}var evidence=group.Value.Generate(full,archive,IntPtr.Zero);var rows=W.MList(evidence["complete_after_compile"]);foreach(Item item in items)if(item.Id==group.Key)generatedCaches.Add(Key(item.Id,item.Row),Map(Map(Map(rows[item.Row])["action"])["serialized_fields"])["byte_arrays@0xC"]);generationEvidence.Add(new Dictionary<string,object>{{"block_id",group.Key},{"original_generation",evidence}});}}
   internal object Report(){return new Dictionary<string,object>{{"contract_sha256",ContractSha},{"generation_completed",entered&&generatedCaches.Count==items.Count},{"original_generations",generationEvidence},{"only_explicit_consumer_prog_compiler_members_derived",true},{"other_business_opaque_rows_preserved",true},{"runtime_execution_verified",false}};}
   public void Dispose(){if(disposed)return;disposed=true;if(archive!=null)archive.Dispose();}
  }
 }
